// 【各位加起来是 k】
// 一行读入两个正整数 n 和 k（n 不超过 10000，k 不超过 36）。
//   1 到 n 里，有几个数的各位数字加起来正好是 k？
// 一个也没有就输出 0。比如 21 的各位加起来是 2 + 1 = 3。
// 例如输入：30 3
// 应该输出：4
// ↓ 从这里开始写

#include <iostream>
using namespace std;

int main() {
    int n = 0, k = 0;
    cin >> n >> k;
    cout << n << " " << k << endl;
    return 0;
}
